all.example:
for (const dog of kcds.characters.Dog.all()) {
  console.info(`${dog.name} (${dog.id}) belongs to ${dog.owner?.nickname ?? 'nobody'}`);
}

all.exampleCs:
foreach (var dog in Dog.All())
{
    Log.Info($"{dog.Name} ({dog.Id}) belongs to {((string.IsNullOrEmpty(dog.Owner?.Nickname) ? "nobody" : dog.Owner?.Nickname))}");
}

getById.example:
kcds.core.Events.fromClient('dog:sit', (player, payload) => {
  const dog = kcds.characters.Dog.getById(Number(payload?.id));
  if (dog && dog.owner === player) {
    dog.mode = 0; // wait
  }
});

getById.exampleCs:
Events.FromClient("dog:sit", (Player player, JsValue payload) =>
{
    var dog = Dog.GetById(payload["id"].AsNumber());
    if (dog != null && dog.Owner == player)
    {
        dog.Mode = 0; // wait
    }
});

