mode.exampleCs:
dog.Mode = 4; // search
Events.On("dogModeChanged", (JsValue changed, JsValue mode) =>
{
    Log.Info($"{changed["name"]} is now in mode {mode}");
});

spawn.example:
kcds.core.Events.on('playerCommand', (player, command) => {
  if (command !== 'dog' || player.dog) {
    return;
  }
  const dog = kcds.characters.Dog.spawn(player, player.position, player.rotation, '', 'Mutt');
  kcds.core.Chat.sendToPlayer(player, `${dog.name} follows you.`);
});

spawn.exampleCs:
Events.On("playerCommand", (Player player, string command) =>
{
    if (command != "dog" || player.Dog != null)
    {
        return;
    }
    var dog = Dog.Spawn(player, player.Position, player.Rotation, "", "Mutt");
    Chat.SendToPlayer(player, $"{dog.Name} follows you.");
});

giveTo.example:
kcds.core.Events.on('playerCommand', (player, command, args) => {
  if (command !== 'givedog' || !player.dog) {
    return;
  }
  const target = kcds.players.Player.all().find((other) => other.nickname === args[0]);
  if (target) {
    player.dog.giveTo(target);
  }
});

giveTo.exampleCs:
Events.On("playerCommand", (Player player, string command, JsValue args) =>
{
    if (command != "givedog" || player.Dog == null)
    {
        return;
    }
    var target = Player.All().FirstOrDefault(other => other.Nickname == args[0].AsString());
    if (target != null)
    {
        player.Dog.GiveTo(target);
    }
});

destroy.exampleCs:
Events.On("playerCommand", (Player player, string command) =>
{
    if (command == "dismissdog" && player.Dog != null)
    {
        player.Dog.Destroy();
    }
});
